add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_free_sample_button' );
add_filter( 'woocommerce_add_cart_item_data', 'perfectpixel_free_sample_cart_data', 10, 2 );
add_filter( 'woocommerce_get_item_data', 'perfectpixel_free_sample_item_data', 10, 2 );
add_action( 'woocommerce_checkout_create_order_line_item', 'perfectpixel_free_sample_order_meta', 10, 3 );

function perfectpixel_free_sample_button() {
	global $product;
	$sample_id = (int) '{{free_sample_product_id}}';
	if ( ! $sample_id || ! $product || $product->get_id() === $sample_id ) {
		return;
	}
	printf(
		'<form method="post" action="%1$s" class="perfectpixel-free-sample" style="margin-bottom:1.5em"><input type="hidden" name="add-to-cart" value="%2$d"><input type="hidden" name="perfectpixel_sample_of" value="%3$d"><button type="submit" class="button">%4$s</button></form>',
		esc_url( $product->get_permalink() ),
		$sample_id,
		(int) $product->get_id(),
		esc_html( '{{free_sample_button}}' )
	);
}

function perfectpixel_free_sample_cart_data( $data, $product_id ) {
	if ( (int) $product_id === (int) '{{free_sample_product_id}}' && ! empty( $_POST['perfectpixel_sample_of'] ) ) {
		$source = wc_get_product( absint( $_POST['perfectpixel_sample_of'] ) );
		if ( $source ) {
			// One line per source product; adding the same sample again only bumps its quantity.
			$data['perfectpixel_sample_of'] = $source->get_id();
		}
	}
	return $data;
}

function perfectpixel_free_sample_item_data( $item_data, $cart_item ) {
	if ( ! empty( $cart_item['perfectpixel_sample_of'] ) ) {
		$item_data[] = array( 'key' => '{{free_sample_meta_label}}', 'value' => get_the_title( $cart_item['perfectpixel_sample_of'] ) );
	}
	return $item_data;
}

function perfectpixel_free_sample_order_meta( $item, $cart_item_key, $values ) {
	if ( ! empty( $values['perfectpixel_sample_of'] ) ) {
		$item->add_meta_data( '{{free_sample_meta_label}}', get_the_title( $values['perfectpixel_sample_of'] ), true );
	}
}
